BuildingFootprint osmTestFootprint(String name) {
  final features =
      (jsonDecode(osmTestFootprintsGeoJson) as Map)['features'] as List;
  for (final feature in features) {
    final props = (feature as Map)['properties'] as Map;
    if (props['name'] == name) {
      final footprint = validFootprint(feature['geometry']);
      if (footprint == null) throw StateError('Invalid OSM footprint: $name');
      return footprint;
    }
  }
  throw StateError('Missing OSM footprint: $name');
}
